-- FUTURE DATABASE BLUEPRINT (PostgreSQL / Supabase)
-- Current portfolio demo uses localStorage only. This is not an active integration.
-- Never store raw card numbers or CVC values. Store provider references/tokens only.
create table profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null, phone text, country text, created_at timestamptz not null default now());
create table room_types (id uuid primary key default gen_random_uuid(), slug text unique not null, name text not null, description text, max_guests integer not null check(max_guests>0), base_rate numeric(10,2) not null check(base_rate>=0), breakfast_rate numeric(10,2) not null default 0 check(breakfast_rate>=0), active boolean not null default true);
create table rooms (id uuid primary key default gen_random_uuid(), room_type_id uuid not null references room_types(id), room_number text unique not null, status text not null default 'active' check(status in ('active','maintenance','inactive')));
create table rate_plans (id uuid primary key default gen_random_uuid(), room_type_id uuid not null references room_types(id), stay_date date not null, nightly_rate numeric(10,2) not null check(nightly_rate>=0), inventory_count integer not null check(inventory_count>=0), unique(room_type_id,stay_date));
create table bookings (id uuid primary key default gen_random_uuid(), booking_reference text unique not null, guest_id uuid not null references profiles(id), check_in date not null, check_out date not null, adults integer not null check(adults>0), children integer not null default 0 check(children>=0), room_count integer not null default 1 check(room_count>0), status text not null default 'pending' check(status in ('pending','confirmed','cancelled','checked_in','checked_out')), currency char(3) not null default 'USD', subtotal numeric(10,2) not null, tax_total numeric(10,2) not null default 0, grand_total numeric(10,2) not null, created_at timestamptz not null default now(), check(check_out>check_in));
create table booking_items (id uuid primary key default gen_random_uuid(), booking_id uuid not null references bookings(id) on delete cascade, room_type_id uuid not null references room_types(id), quantity integer not null default 1 check(quantity>0), nightly_rate numeric(10,2) not null, breakfast_selected boolean not null default false, breakfast_guest_count integer not null default 0, line_total numeric(10,2) not null);
create table payments (id uuid primary key default gen_random_uuid(), booking_id uuid not null references bookings(id), provider text not null, provider_payment_id text, amount numeric(10,2) not null, currency char(3) not null default 'USD', status text not null check(status in ('requires_action','authorized','paid','failed','refunded')), created_at timestamptz not null default now());
create index bookings_guest_id_idx on bookings(guest_id);
create index bookings_dates_idx on bookings(check_in,check_out);
create index booking_items_booking_id_idx on booking_items(booking_id);
